from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    stack = []
    groups = []
    current_group = []
    for char in paren_string:
        if char == '(':
            stack.append(current_group)
            current_group = []
        elif char == ')':
            if stack:
                groups.append(''.join(current_group))
                current_group = []
        else:
            current_group.append(char)
    if current_group:
        groups.append(''.join(current_group))
    return groups

from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    result = []
    current_depth = 0
    for char in paren_string:
        if char == '(':
            current_depth += 1
        elif char == ')':
            current_depth -= 1
        result.append(current_depth)
    return result

def flip_case(string: str) -> str:
    """ For a given string, flip lowercase characters to uppercase and uppercase to lowercase.
    >>> flip_case('Hello')
    'hELLO'
    """
    return string.swapcase()

import math

def poly(xs: list, x: float):
    """
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
    """
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])

def find_zero(xs: list):
    """ xs are coefficients of a polynomial.
    find_zero find x such that poly(x) = 0.
    find_zero returns only only zero point, even if there are many.
    Moreover, find_zero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    """
    if len(xs) % 2 != 0:
        raise ValueError("List must have even number of coefficients")
    if not xs:
        raise ValueError("List cannot be empty")
    x = 0.0
    for coeff in xs:
        if abs(coeff) > 1e-10:
            x += 1e-10
    while True:
        current = poly(x)
        if abs(current) < 1e-10:
            return x
        x += 1e-10

def incr_list(l: list):
    """Return list with elements incremented by 1."""
    return [x + 1 for x in l]

def below_threshold(l: list, t: int):
    """Return True if all numbers in the list l are below threshold t."""
    return all(x < t for x in l)

def monotonic(l: list):
    """Return True is list elements are monotonically increasing or decreasing."""
    if len(l) <= 1:
        return True
    is_increasing = True
    is_decreasing = True
    for i in range(len(l) - 1):
        current = l[i]
        next_val = l[i + 1]
        if next_val > current:
            is_increasing = False
        elif next_val < current:
            is_decreasing = False
        else:
            is_increasing = False
            is_decreasing = False
    return is_increasing or is_decreasing

def will_it_fly(q, w):
    sum_q = sum(q)
    if sum_q <= w:
        return True
    return q == q[::-1]

def prime_length(string):
    """Write a function that takes a string and returns True if the string
    length is a prime number or False otherwise
    Examples
    prime_length('Hello') == True
    prime_length('abcdcba') == True
    prime_length('kittens') == True
    prime_length('orange') == False
    """
    def is_prime(n):
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    s = len(string)
    return is_prime(s)

def get_row(lst, x):
    result = []
    for i, row in enumerate(lst):
        if x in row:
            result.append((i, row.index(x)))
    result.sort(key=lambda coord: (coord[0], -coord[1]))
    return result

def even_odd_palindrome(n):
    count_even = 0
    count_odd = 0
    for i in range(1, n):
        s = str(i)
        if s[0] == s[-1]:
            if i % 2 == 0:
                count_even += 1
            else:
                count_odd += 1
    return (count_even, count_odd)

def reverse_delete(s, c):
    filtered = [char for char in s if char not in c]
    filtered_str = ''.join(filtered)
    is_palindrome = filtered_str == filtered_str[::-1]
    return (filtered_str, is_palindrome)

def select_words(s, n):
    words = s.split()
    result = []
    for word in words:
        consonants = sum(1 for c in word if c.lower() not in {'a', 'e', 'i', 'o', 'u'})
        if consonants == n:
            result.append(word)
    return result

def prod_signs(arr):
    if not arr:
        return None
    product = 1
    for num in arr:
        product *= num
    return product * sum(1 if num == 0 else 1 for num in arr)

def words_in_sentence(sentence):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                return False
        return True

    words = sentence.split()
    result = []
    for word in words:
        if is_prime(len(word)):
            result.append(word)
    return ' '.join(result)

def bf(planet1, planet2):
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]
    if planet1 not in planets or planet2 not in planets:
        return ()
    if planet1 == planet2:
        return ()
    if planet1 > planet2:
        planet1, planet2 = planet2, planet1
    planets_sorted = sorted(planets, key=lambda x: (abs(x - planet1), x))
    return planets_sorted[1:]

def find_max(words):
    def unique_count(s):
        return len(set(s))

    max_count = -1
    result = ""

    for word in words:
        current_count = unique_count(word)
        if current_count > max_count:
            max_count = current_count
            result = word
        elif current_count == max_count:
            if word < result:
                result = word

    return result
